// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    RecordingToken token;

    function setUp() public {
        c = new PoCGame(address(this), 0);
        token = new RecordingToken();
    }

    function testFuzz_property(address tokenOwner, uint256 tokens) public {
        vm.assume(tokenOwner != address(0));
        bool ok = c.transferAnyERC20Token(address(token), tokenOwner, tokens);
        assertTrue(ok && token.lastTo() == tokenOwner);
    }
}

contract RecordingToken {
    address public lastTo;
    uint256 public lastAmount;

    function transfer(address to, uint256 tokens) public returns (bool success) {
        lastTo = to;
        lastAmount = tokens;
        return true;
    }
}
